typedef struct {VkBuffer buffer;VkDeviceMemory memory;void*mapped;} Buffer;
static VkInstance instance;static VkDevice device;static VkPhysicalDevice physical;static VkQueue queue;static VkCommandPool pool;static VkCommandBuffer command;static VkFence fence;static VkPhysicalDeviceMemoryProperties memory_properties;static unsigned gpu_cases,errors;static VkDebugUtilsMessengerEXT messenger;static bool validation_enabled;
