static unsigned memory_type(unsigned bits,VkMemoryPropertyFlags flags){for(unsigned i=0;i<memory_properties.memoryTypeCount;i++)if((bits&(1u<<i))&&(memory_properties.memoryTypes[i].propertyFlags&flags)==flags)return i;abort();}
static Buffer make_buffer(size_t n,VkBufferUsageFlags usage){Buffer b={0};VkBufferCreateInfo ci={.sType=VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO,.size=n,.usage=usage};CHECK(vkCreateBuffer(device,&ci,NULL,&b.buffer));VkMemoryRequirements mr;vkGetBufferMemoryRequirements(device,b.buffer,&mr);VkMemoryAllocateInfo ai={.sType=VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO,.allocationSize=mr.size,.memoryTypeIndex=memory_type(mr.memoryTypeBits,VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT|VK_MEMORY_PROPERTY_HOST_COHERENT_BIT)};CHECK(vkAllocateMemory(device,&ai,NULL,&b.memory));CHECK(vkBindBufferMemory(device,b.buffer,b.memory,0));CHECK(vkMapMemory(device,b.memory,0,VK_WHOLE_SIZE,0,&b.mapped));return b;}
