   for(unsigned y=0;y<HEIGHT;y++)for(unsigned x=0;x<WIDTH;x++)for(unsigned c=0;c<4;c++){bool white=x>=x0&&x<x1&&y>=y0&&y<y1;unsigned at=(y*WIDTH+x)*4+c;if(format)assert(((float*)output.mapped)[at]==(white?1.0f:0.0f));else assert(((uint8_t*)output.mapped)[at]==(white?255:0));}gpu_cases++;vkDestroyPipeline(device,p,NULL);
